INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `Text_lang`, `Text1_lang`, `VerifiedBuild`) VALUES
(115258, 'ruRU', '', 'Воистину, так и будет.', 24330),
(115263, 'ruRU', '', 'Я сделал то, что, как мне казалось, было—', 24330),
(115279, 'ruRU', '', 'Список предателей? Тебе нужно немедленно доставить это лейтенанту Пьету.', 24330),
(115281, 'ruRU', '', 'Слышал, у тебя есть имена мятежных отбросов? Быстро, давай их сюда.', 24330),
(115282, 'ruRU', '', 'Глупец, за тобой следили! К оружию!', 24330),
(115291, 'ruRU', '', 'Прошу... даже несколько капель аркового вина могли бы спасти мой разум от безумия...', 24330),
(115292, 'ruRU', '', 'Ты выглядишь сильным... у тебя наверняка есть лишнее арковое вино!', 24330),
(115293, 'ruRU', '', 'Я чувствую, как мой разум... ускользает... нужно арковое вино...', 24330),
(115294, 'ruRU', '', 'Я принёс тебе немного аркового вина... пей!', 24330),
(115301, 'ruRU', '', 'Никчёмные! Готовьте оборону. Я получу огромное удовольствие, убивая тебя, $n.', 24330),
(115303, 'ruRU', '', 'Предложение: 800x |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t|Hcurrency:1155|h|cFFFFFFFF Древняя мана|h|r', 24330),
(115335, 'ruRU', '', 'Подожди. Мы не знаем силы нашего врага. Кто знает, во что ты так спешишь вступить?', 24330),
(115361, 'ruRU', '', 'Вам не следует быть здесь, малыши. Атаки Пылающего Легиона неослабевающие. Даже я получил немало ран.', 24330),
(115362, 'ruRU', '', 'Готовься, наши враги приближаются!', 24330),
(115365, 'ruRU', '', 'Фу Цзань выбрал нового спутника. Великие свершения и великие испытания ждут тебя, малыш. А пока тебе стоит вернуться домой, отдохнуть и подготовиться к тому, что грядёт.', 24330),
(115367, 'ruRU', '', 'Прощай, малыш.', 24330),
(115370, 'ruRU', '', 'Рад видеть тебя снова. Вантир достал ещё аркового вина, чтобы ты распределил его.', 24330),
(115393, 'ruRU', '', 'Время не ждёт. Нам нужно двигаться!', 24330),
(115394, 'ruRU', '', 'Каждое мгновение нашего бездействия Легион становится сильнее.', 24330),
(115395, 'ruRU', '', 'В отсутствие лорда Иллидана ты старший член нашего ордена. Мы не можем принять это решение без тебя.', 24330),
(115396, 'ruRU', '', 'Дай знать, когда будешь готов.', 24330),
(115397, 'ruRU', '', 'Лишь надеюсь, что этого хватит. Слишком многие в городе на пределе...', 24330),
(115398, 'ruRU', '', 'Становится всё труднее находить лишнее Арковое вино... но то, что удаётся найти, мы делим с самыми нуждающимися из нас.', 24330),
(115400, 'ruRU', '', 'Это место хранит много секретов, но редко их раскрывает.', 24330),
(115401, 'ruRU', '', 'Внешний мир слишком большой и шумный. У меня есть всё, что нужно, прямо здесь.', 24330),
(115402, 'ruRU', '', 'В Чертогах стало ужасно шумно с тех пор, как прибыла новая Тирисгарда. Мне куда больше нравилось слушать, как поют мыши среди теней.', 24330),
(115403, 'ruRU', '', 'Благодарю вас, малыши. Я могу исцелить свои раны, но мне нужно время, чтобы моя магия подействовала. Наши хитроумные враги воспользуются этой возможностью для удара.', 24330),
(115404, 'ruRU', '', 'Защищайте меня, пока я восстанавливаюсь. Если мы падём, за нами последует вся Пандария.', 24330),
(115407, 'ruRU', '', 'В знак моей благодарности позволь мне проводить тебя домой.', 24330),
(115408, 'ruRU', '', 'Стихии хитрые со своими секретами, но я смотрю и я слушаю. Коли знаешь, как говорить с ними, их секреты тоже станут твоими.', 24330),
(115410, 'ruRU', '', 'Сила колонны Водоворота была истощена во время защиты Сердца Азерота. Колонна будет восстанавливаться медленно, но этот процесс может занять десятилетия, а такой роскоши у нас нет. Нам нужно найти способ ускорить её восстановление.', 24330),
(115411, 'ruRU', '', 'Превосходно! Дар лорда Нептулона уже творит чудеса. Похоже, камень снова проводит мою силу воды.', 24330),
(115412, 'ruRU', '', 'Мы продолжаем продвигаться, Дальновидец. Колонна Водоворота оживлена силой воздуха. Если повезёт, мы скоро сможем восстановить её полный потенциал.', 24330),
(115413, 'ruRU', '', 'Твоя помощь была незаменима для моего продвижения здесь, Дальновидец. Камень почти завершён. С восстановленными силами воды, воздуха и земли остаётся лишь стихия огня.', 24330),
(115414, 'ruRU', '', 'Я не мог быть более доволен, Дальновидец. Восстановление колонны Водоворота до максимальных возможностей потребовало немало труда, но оно того стоило.$B$BДавай, попробуй сам — камень могущественно проводит стихии!', 24330),
(115417, 'ruRU', '', 'Мы можем использовать Кровавый камень. Он будет достаточно мощным, чтобы контролировать сестёр, когда они в ослабленном состоянии.', 24330),
(115427, 'ruRU', '', 'Я могу сделать многое, чтобы помочь укрепить твой орденский зал, хотя придётся принять несколько непростых решений.', 24330),
(115428, 'ruRU', '', 'Я всё ещё могу показать пару магических трюков, если захочу...', 24330),
(115429, 'ruRU', '', 'Ох, смотри! Разве она не удивительна! Она будет верно служить тебе, $n, если попросишь её вежливо.', 24330),
(115437, 'ruRU', '', 'Ах да, я определённо могу что-то сделать с этой водой. Мне понадобится время, чтобы поработать с ней. Благодарю, Дальновидец.', 24330);
